43	        int action = event.getAction();
44	
45	        if (action == MotionEvent.ACTION_UP ||
46	                action == MotionEvent.ACTION_DOWN) {
47	            int x = (int) event.getX();
48	            int y = (int) event.getY();
49	
50	            x -= widget.getTotalPaddingLeft();
51	            y -= widget.getTotalPaddingTop();
52	
53	            x += widget.getScrollX();
54	            y += widget.getScrollY();
55	
56	            Layout layout = widget.getLayout();
57	            int line = layout.getLineForVertical(y);
58	            int off = layout.getOffsetForHorizontal(line, x);
59	
60	            ClickableSpan[] link = buffer.getSpans(off, off, ClickableSpan.class);
61	
62	            if (link.length != 0) {
63	                if (action == MotionEvent.ACTION_UP) {
64	                    link[0].onClick(widget);
65	                } else if (action == MotionEvent.ACTION_DOWN) {
66	                    Selection.setSelection(buffer,
67	                            buffer.getSpanStart(link[0]),
68	                            buffer.getSpanEnd(link[0]));
69	                }
70	
71	                return true;
72	            } else {
73	                Selection.removeSelection(buffer);
74	                Touch.onTouchEvent(widget, buffer, event);
75	                return false;
76	            }
77	        }
